procedure @@proc@@(p_val in varchar2) is
  l_rows number;
begin
  execute immediate 'delete from @@tab@@ where @@col@@ = ' || p_val; -- @expect
  l_rows := sql%rowcount;
  if l_rows > 0 then
    dbms_output.put_line('removed rows: ' || l_rows);
  end if;
end @@proc@@;

function @@proc@@(p_table in varchar2) return number is
  l_sql varchar2(400);
  l_cnt number;
begin
  l_sql := 'select count(*) from ' || p_table;
  l_sql := l_sql || ' where @@col@@ is not null';
  execute immediate l_sql into l_cnt; -- @expect
  return l_cnt;
end @@proc@@;

function @@proc@@(p_filter in varchar2) return sys_refcursor is
  l_cur sys_refcursor;
begin
  open l_cur for -- @expect
    'select id, @@col@@ '
    || 'from @@tab@@ '
    || 'where @@col2@@ = ' || p_filter;
  return l_cur;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_rows number;
begin
  execute immediate -- @expect
    'delete from ' || sys_context('userenv', 'current_schema')
    || '.@@tab@@ where id = :1'
    using p_id;
  l_rows := sql%rowcount;
  dbms_output.put_line(l_rows);
end @@proc@@;

procedure @@proc@@(p_cond in varchar2, p_val in number, p_id in number) is
  l_rows number;
begin
  execute immediate 'update @@tab@@ set @@col@@ = :1 where ' || p_cond -- @expect
    || ' and id = :2'
    using p_val, p_id;
  l_rows := sql%rowcount;
  dbms_output.put_line(l_rows);
  commit;
end @@proc@@;

