procedure @@proc@@(p_val in number, p_id in number) is
  l_rows number;
begin
  execute immediate 'update @@tab@@ set @@col@@ = :1 where id = :2'
    using p_val, p_id;
  l_rows := sql%rowcount;
  dbms_output.put_line(l_rows);
end @@proc@@;

function @@proc@@ return number is
  l_cnt number;
begin
  execute immediate 'select count(*) from ' || '@@tab@@'
    || ' where @@col@@ is null' into l_cnt;
  dbms_output.put_line(l_cnt);
  return l_cnt;
  -- the statement text is built from literals only
end @@proc@@;

function @@proc@@(p_owner in varchar2, p_table in varchar2) return number is
  l_cnt number;
begin
  execute immediate 'select count(*) from '
    || dbms_assert.enquote_name(p_owner) || '.'
    || dbms_assert.enquote_name(p_table)
    into l_cnt;
  return l_cnt;
end @@proc@@;

procedure @@proc@@(p_full in boolean) is
  l_sql varchar2(200);
begin
  l_sql := 'truncate table @@tab@@';
  if not p_full then
    l_sql := 'delete from @@tab@@ where @@col@@ is null';
  end if;
  execute immediate l_sql;
  dbms_output.put_line('cleanup finished');
end @@proc@@;

function @@proc@@(p_val in varchar2) return sys_refcursor is
  l_cur sys_refcursor;
begin
  open l_cur for
    select id, @@col@@
      from @@tab@@
     where @@col2@@ = p_val;
  return l_cur;
end @@proc@@;
